const config = {apiBaseUrl: 'http://api:8000', pollIntervalSeconds: 5, maxPolls: 120};
config.apiBaseUrl = config.apiBaseUrl.replace(/\/+$/, '');
if (!/^https?:\/\/[^\s/?#]+(?::\d+)?(?:\/[^?#]*)?$/.test(config.apiBaseUrl) || config.apiBaseUrl.includes('@')) {
  throw new Error('Set a valid http(s) API base URL without credentials, query or fragment');
}
if (!Number.isInteger(config.maxPolls) || config.maxPolls < 1 ||
    !Number.isFinite(config.pollIntervalSeconds) || config.pollIntervalSeconds < 1) {
  throw new Error('maxPolls must be positive; pollIntervalSeconds must be at least 1');
}
return [{json: config}];

const response = $input.first().json;
if (!['accepted', 'already_running'].includes(response.status)) {
  throw new Error('Unexpected /run response; inspect the HTTP node output');
}
return [{json: {trigger: response.status,
  note: response.status === 'already_running' ? 'Observing the existing run; no second batch was started.' : 'Run accepted.'}}];

const config = $('Connection Settings').first().json;
const status = $input.first().json;
if (!['idle', 'processing', 'error'].includes(status.status)) {
  throw new Error('Unexpected /status response; inspect the HTTP node output');
}
const poll = $runIndex + 1;
const stillProcessing = status.status === 'processing';
const timedOut = stillProcessing && poll >= config.maxPolls;
let outcome = 'processing';
if (timedOut) outcome = 'monitor_timeout';
else if (status.status === 'error') outcome = 'run_error';
else if (status.status === 'idle') {
  if (status.error) outcome = 'finished_with_job_errors';
  else if (status.stage === 'Stopped' || Number(status.pending) > 0) outcome = 'incomplete_or_stopped';
  else if (status.stage !== 'Run finished') outcome = 'unconfirmed_idle';
  else outcome = 'finished';
}
return [{json: {poll, outcome, continuePolling: stillProcessing && !timedOut,
  trigger: $('Validate Start Response').first().json.trigger,
  status, message: timedOut ? 'Monitoring limit reached. The Python worker may still be running; check its dashboard.' :
    status.error || (outcome === 'incomplete_or_stopped' ? 'Processing stopped or pending jobs remain.' : outcome)}}];

const data = $input.first().json;
return [{json: {...data, simulated: false,
  note: 'Counts are the Python worker current snapshot, not per-run totals. Inspect Baserow Output URL for videos. The API has no run ID or per-job result endpoint.'}}];
